const fs = require("fs");
const path = require("path");

// The canonical FileExportPlugin is generated by configure-android-share.js.
// This step deliberately validates that implementation instead of overwriting it.
const config = JSON.parse(fs.readFileSync(path.join(__dirname, "capacitor.config.json"), "utf8"));
const packagePath = config.appId.split(".").join(path.sep);
const pluginPath = path.join(__dirname, "android", "app", "src", "main", "java", packagePath, "FileExportPlugin.java");
if (!fs.existsSync(pluginPath)) {
  throw new Error("FileExportPlugin.java is missing. Run configure-android-share.js first.");
}
const source = fs.readFileSync(pluginPath, "utf8");
const activityPath = path.join(__dirname, "android", "app", "src", "main", "java", packagePath, "MainActivity.java");
if (!fs.existsSync(activityPath)) throw new Error("MainActivity.java is missing. Run configure-android-share.js first.");
const activity = fs.readFileSync(activityPath, "utf8");
const onCreateStart = activity.indexOf("public void onCreate(Bundle savedInstanceState)");
const earlyDrawInit = activity.indexOf("WebView.enableSlowWholeDocumentDraw()", onCreateStart);
const bridgeInit = activity.indexOf("super.onCreate(savedInstanceState)", onCreateStart);
if (onCreateStart < 0 || earlyDrawInit < 0 || bridgeInit < 0 || earlyDrawInit > bridgeInit || !activity.includes("import android.webkit.WebView;")) {
  throw new Error("Whole-document WebView drawing must be enabled in MainActivity before BridgeActivity creates the app WebView.");
}
const required = [
  "saveHtmlAsImages",
  "printHtml",
  "writeWebViewToPdf",
  "new android.graphics.pdf.PdfDocument()",
  "new android.graphics.pdf.PdfDocument.PageInfo.Builder(width,height,index+1).create()",
  "v.setLayoutParams(new FrameLayout.LayoutParams(width,contentHeight))",
  "v.layout(0,0,width,contentHeight)",
  "canvas.clipRect(0,0,width,height)",
  "canvas.translate(0,-index*height)",
  "v.draw(canvas)",
  "document.writeTo(output)",
  "WebView.enableSlowWholeDocumentDraw()",
  "PdfRenderer",
  "page.render(bitmap",
  "bitmap.compress(Bitmap.CompressFormat.PNG,100,out)",
  "nonWhite==0",
  "removePartialImages.run()",
  "renderer.openPage(index)",
  "page.close()",
  "PrintJob job=pm.print(jobName,v.createPrintDocumentAdapter(jobName),attributes)"
];
const missing = required.filter(marker => !source.includes(marker));
if (missing.length) {
  throw new Error("The canonical Android PDF/image exporter is incomplete: " + missing.join(", "));
}
if (source.includes("nativeAdapter.onLayout(") || source.includes("nativeAdapter.onWrite(")) {
  throw new Error("Image export must not invoke hidden Android print callbacks directly.");
}
console.log("Verified whole-document WebView rendering, paginated PdfDocument-to-PNG export, blank-page detection, and cleanup.");
